import unittest

from ranking import rank_players


class TestRanking(unittest.TestCase):
    def test_desc(self):
        players = [{'name': 'a', 'score': 3}, {'name': 'b', 'score': 9}, {'name': 'c', 'score': 6}]
        self.assertEqual([p['name'] for p in rank_players(players)], ['b', 'c', 'a'])

    def test_empty(self):
        self.assertEqual(rank_players([]), [])


if __name__ == '__main__':
    unittest.main()
